373:   public void error(Throwable throwable) {
374:     ServerErrorHandler serverErrorHandler = get(ServerErrorHandler.class);
375:     throwable = unpackThrowable(throwable);
376: 
377:     ThrowableHolder throwableHolder = getRequest().maybeGet(ThrowableHolder.class).orElse(null);
378:     if (throwableHolder == null) {
379:       getRequest().add(ThrowableHolder.class, new ThrowableHolder(throwable));
380: 
381:       try {
382:         serverErrorHandler.error(this, throwable);
383:       } catch (Throwable errorHandlerThrowable) {
384:         onErrorHandlerError(serverErrorHandler, throwable, errorHandlerThrowable);
385:       }
386:     } else {
387:       onErrorHandlerError(serverErrorHandler, throwableHolder.getThrowable(), throwable);
388:     }
389:   }
