391:   private void onErrorHandlerError(ServerErrorHandler serverErrorHandler, Throwable original, Throwable errorHandlerThrowable) {
392:     String msg = "Throwable thrown by error handler " + serverErrorHandler + " while handling throwable\n"
393:       + "Original throwable: " + getStackTraceAsString(original) + "\n"
394:       + "Error handler throwable: " + getStackTraceAsString(errorHandlerThrowable);
395: 
396:     LOGGER.error(msg);
397: 
398:     Response response = requestConstants.response.status(500);
399:     if (getRegistry().isDevelopment()) {
400:       response.send(msg);
401:     } else {
402:       response.send();
403:     }
404:   }
