import groovy.lang.Writable;
import org.vertx.java.core.Handler;

import java.util.LinkedList;
import java.util.List;

public class RenderingTemplate implements Handler<Writable> {

  private final TemplateId templatePath;
  private Writable writable;
  private String content;

  private final List<RenderingTemplate> children = new LinkedList<RenderingTemplate>();

  public RenderingTemplate(TemplateId templatePath) {
    this.templatePath = templatePath;
  }

  public List<RenderingTemplate> getChildren() {
    return children;
  }

  public TemplateId getId() {
    return templatePath;
  }

  @Override
  public void handle(Writable writable) {
    this.writable = writable;
  }

  public void complete() {
    if (content != null) {
      return;
    }

    for (RenderingTemplate child : children) {
      child.complete();
    }

    content = writable == null ? "<exception>" : writable.toString();
  }

  @Override
  public String toString() {
    if (writable == null) {
      return "<rendering>";
    } else if (content == null) {
      return "<pending>";
    } else {
      return content;
    }
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }

    RenderingTemplate that = (RenderingTemplate) o;

    if (!templatePath.equals(that.templatePath)) {
      return false;
    }

    return true;
  }

  @Override
  public int hashCode() {
    return templatePath.hashCode();
  }
}
